class Solution {
    int res = 0;
public:
    int longestZigZag(TreeNode* root) {
        dfs(root, 0, true);
        dfs(root, 0, false);
        return res;
    }

    void dfs(TreeNode* node, int length, bool isLeft) {
        if (!node) return;
        res = max(res, length);
        if (isLeft) {
            dfs(node->left, 1, true);
            dfs(node->right, length + 1, false);
        } else {
            dfs(node->right, 1, false);
            dfs(node->left, length + 1, true);
        }
    }
};
